import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFileSync,existsSync,mkdirSync,writeFileSync} from 'node:fs';
import {resolve,dirname,extname} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const {checkout}=JSON.parse(readFileSync(resolve(root,'.work/source.json'),'utf8'));
const {chromium}=await import(pathToFileURL(resolve(checkout,'apps/web/node_modules/playwright/index.mjs')).href);
const directory=resolve(root,process.env.CONVERSATION_BUNDLE??'.work/services');
const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.wasm':'application/wasm','.woff2':'font/woff2','.svg':'image/svg+xml','.json':'application/json'};
const server=createServer((request,response)=>{const path=resolve(directory,'.'+decodeURIComponent(new URL(request.url,'http://localhost').pathname));if(!path.startsWith(directory+'/')){response.writeHead(403);response.end();return;}if(!existsSync(path)){response.writeHead(404);response.end();return;}response.setHeader('Content-Type',mime[extname(path)]??'application/octet-stream');response.end(readFileSync(path));});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const origin=`http://127.0.0.1:${server.address().port}`;
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:900,height:1100}});
const errors=[],network=[],consoleErrors=[];
page.on('pageerror',error=>errors.push(error.message));page.on('console',message=>{if(message.type()==='error')consoleErrors.push(message.text());});
page.on('request',request=>{if(!request.url().startsWith(origin)&&!request.url().startsWith('data:')&&!request.url().startsWith('blob:'))network.push(request.url());});
page.on('websocket',socket=>network.push(socket.url()));
await page.addInitScript(()=>{window.__bridge=[];window.__draft='Existing typed 🐈';window.__race=false;window.webkit={messageHandlers:{tabConversation:{postMessage(message){window.__bridge.push(message);if(message.type!=='action')return;const action=message.action;let reply={requestId:message.requestId,ok:true,result:true};if(action.kind==='useArtifactTemplate'&&action.phase==='read'){reply.result={prompt:window.__draft};if(window.__race){window.__race=false;window.__draft+=' user typed while waiting';}}else if(action.kind==='useArtifactTemplate'&&action.phase==='append'){if(action.expectedPrompt!==window.__draft)reply={requestId:message.requestId,ok:false,error:'The composer draft changed; try adding the template again.'};else window.__draft+=action.append;}else reply={requestId:message.requestId,ok:false,error:'Unexpected fixture action '+action.kind};queueMicrotask(()=>window.TabConversation.resolve(reply));}}}};});
const text='::artifact-template{skill_name="artifact-template-hello-world" skill_directory="/skills/artifact-template-hello-world" display_name="Hello World" artifact_kind="document"}';
const base={bridgeVersion:1,sessionId:'session',projectId:'project',environmentId:'project',connectionState:'live',revision:1,theme:'light',cwd:'/workspace',status:'idle',turns:[],items:[{id:'answer',kind:'assistant',text,isComplete:true}],messages:[],font:{interfaceSize:16,promptSize:14,codeSize:13},capabilities:{nativeActions:true,useArtifactTemplate:true}};
const checks=[];
try{
 await page.goto(origin+'/index.html',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.TabConversation);
 await page.evaluate(snapshot=>window.TabConversation.update(snapshot),base);
 await page.getByRole('group',{name:'Hello World template'}).waitFor();
 const use=page.getByRole('button',{name:'Use template',exact:true});
 await use.click();
 const expected='Existing typed 🐈 Create a document using this $artifact-template-hello-world about…';
 await page.waitForFunction(value=>window.__draft===value,expected);
 const first=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').map(item=>item.action));
 assert.deepEqual(first.map(action=>[action.kind,action.phase]),[['useArtifactTemplate','read'],['useArtifactTemplate','append']]);
 assert.equal(first[1].expectedPrompt,'Existing typed 🐈');assert.equal(first[1].append,' Create a document using this $artifact-template-hello-world about…');
 checks.push('actual source template card appends the exact source prompt after existing text');
 await use.click();await page.waitForFunction(()=>window.__bridge.filter(item=>item.type==='action'&&item.action.phase==='append').length===2);
 assert.equal(await page.evaluate(()=>window.__draft),expected);
 assert.equal(await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action'&&item.action.phase==='append').at(-1).action.append),'');
 checks.push('repeated template use deduplicates while retaining the native focus action');
 await page.evaluate(()=>{window.__draft='New draft';window.__race=true;});await use.click();
 await page.getByText('The composer draft changed; try adding the template again.',{exact:true}).waitFor();
 assert.equal(await page.evaluate(()=>window.__draft),'New draft user typed while waiting');
 checks.push('concurrent typing is preserved and produces the actual source error toast');
 const before=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').length);
 await page.evaluate(snapshot=>window.TabConversation.update({...snapshot,revision:2,capabilities:{nativeActions:true}}),base);
 await use.click();await page.getByText('Template insertion is unavailable in this conversation.',{exact:true}).waitFor();
 assert.equal(await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').length),before);
 checks.push('unavailable insertion produces an explicit source refusal instead of upstream noop');
 const actions=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').map(item=>item.action.kind));
 assert.ok(actions.every(kind=>kind==='useArtifactTemplate'));
 const diagnostics=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='error'||item.type==='renderDiagnostic'&&item.scope!=='resize-observer'&&!(item.scope==='native-action'&&['The composer draft changed; try adding the template again.','Template insertion is unavailable in this conversation.'].includes(item.message))));
 assert.deepEqual(await page.evaluate(()=>window.__bridge.filter(item=>item.type==='renderDiagnostic'&&item.scope==='native-action').map(item=>item.message)),['The composer draft changed; try adding the template again.','Template insertion is unavailable in this conversation.']);
 assert.deepEqual(diagnostics,[]);assert.deepEqual(errors,[]);assert.deepEqual(consoleErrors,[]);assert.deepEqual(network,[]);
 checks.push('template use sends no message and starts no upstream service');
 const output=resolve(root,'.work/qa/artifact-template');mkdirSync(output,{recursive:true});await page.screenshot({path:resolve(output,'artifact-template.png'),fullPage:true});writeFileSync(resolve(output,'report.json'),JSON.stringify({checks,errors,network,diagnostics},null,2));
 process.stdout.write(JSON.stringify({checks,errors,network,diagnostics},null,2)+'\n');
}finally{await browser.close();server.close();}
